for id,name,osmname,lon,lat,desc,style in rows:
 p=places.get(osmname);lon=p['lon'] if p else lon;lat=p['lat'] if p else lat;x,y=T.transform(lon,lat)
 slug={'grayton':'grayton-beach','rosemary':'rosemary-beach','alys':'alys-beach'}.get(id,id)
 d={'id':id,'town':'30a','name':name,'lon':lon,'lat':lat,'x':x/1000,'y':y/1000,'description':desc,'kind':'walk','style':style,'source':'https://www.visitsouthwalton.com/neighborhoods/'+slug+'/','positionSource':f'https://www.openstreetmap.org/node/{p["id"]}' if p else 'https://www.visitsouthwalton.com/neighborhoods/dune-allen/','osmNode':p['id'] if p else None,'positionStatus':'OSM place label anchor; not a legal district centroid' if p else 'Approximate guide anchor; survey verification pending'}
