  pr={'min':3189330,'max':14615000,'source':'https://alysbeach.com/real-estate-listings/','checked':'2026-10-16','scope':'Available listings on developer page: condos and houses; under-contract listings excluded','sourcePages':['https://alysbeach.com/real-estate-listings/'],'listings':[{'address':'Varian 201','priceValue':3189330},{'address':'185 Elbow Beach Road','priceValue':14615000}]}
